sys_script.script:
(function executeRule(current, previous) {
    var PROP_NAME = 'x_2056099_indust_0.supplier.performance_threshold';
    var DEFAULT_THRESHOLD = '75';
    var TABLE = 'x_2056099_indust_0_supp_score';
    var EVENT_NAME = 'x_2056099_indust_0.perf_below_threshold';

    var threshold = parseInt(gs.getProperty(PROP_NAME, DEFAULT_THRESHOLD), 10);
    var newScore = parseFloat(current.getValue('overall_score_pct') || '0');
    var previousScore = previous
        ? parseFloat(previous.getValue('overall_score_pct') || '0')
        : 0;
    var currentSupplierStatus = current.getValue('supplier_status') || '';

    gs.info(
        'Supplier Threshold Check: Supplier=' +
            current.supplier.getDisplayValue() +
            ', NewScore=' + newScore +
            ', PreviousScore=' + previousScore +
            ', Threshold=' + threshold
    );

    if (newScore < threshold) {
        // Score is below threshold — flag for procurement review
        var gr = new GlideRecord(TABLE);
        if (gr.get(current.getUniqueValue())) {
            gr.setWorkflow(false); // Prevent recursive business rule firing
            gr.setValue('supplier_status', 'performance_review_required');
            gr.setValue('procurement_review_required', true);
            gr.update();
        }

        // Fire event so email notification is sent to procurement group
        gs.eventQueue(EVENT_NAME, current, previousScore + '', newScore + '');

        gs.info(
            'Supplier ' + current.supplier.getDisplayValue() +
            ' flagged for procurement review. Score ' + newScore +
            '% is below threshold ' + threshold + '%.'
        );
    } else if (
        newScore >= threshold &&
        currentSupplierStatus == 'performance_review_required'
    ) {
        // Score recovered above threshold while still flagged — clear review flag only
        // Do NOT automatically change supplier_status; procurement makes that decision
        var grClear = new GlideRecord(TABLE);
        if (grClear.get(current.getUniqueValue())) {
            grClear.setWorkflow(false);
            grClear.setValue('procurement_review_required', false);
            grClear.update();
        }

        gs.info(
            'Supplier ' + current.supplier.getDisplayValue() +
            ' score recovered to ' + newScore +
            '%. Procurement review flag cleared. Supplier status unchanged.'
        );
    }
})(current, previous);
